-- 6. SYNCHRONIZE IDENTITY SEQUENCES TO HIGHEST MIGRATED IDS
SELECT setval(pg_get_serial_sequence('materials', 'id'), COALESCE((SELECT MAX(id) FROM materials), 1));
SELECT setval(pg_get_serial_sequence('invoices', 'id'), COALESCE((SELECT MAX(id) FROM invoices), 1));
SELECT setval(pg_get_serial_sequence('invoice_items', 'id'), COALESCE((SELECT MAX(id) FROM invoice_items), 1));
SELECT setval(pg_get_serial_sequence('transfers', 'id'), COALESCE((SELECT MAX(id) FROM transfers), 1));
SELECT setval(pg_get_serial_sequence('stock_adjustments', 'id'), COALESCE((SELECT MAX(id) FROM stock_adjustments), 1));
